    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
    match key.code {
        KeyCode::Char('d') if ctrl => Some(ConfirmDeleteAction::Yes),
        KeyCode::Esc => Some(ConfirmDeleteAction::No),
        _ => None,
    }
}

